/* Independent SAM health-check fallback: keep the button responsive even if the
   optional Universal Rig controller fails to load or initialize. Capture phase
   claims the click first; the controller's delegated handler then safely skips. */
document.addEventListener('click',async event=>{
 const button=event.target&&event.target.closest?event.target.closest('#itcvRigCheck'):null;
 if(!button||button.dataset.checking==='1')return;
 event.preventDefault();event.stopImmediatePropagation();
 button.dataset.checking='1';button.disabled=true;button.textContent='Memeriksa SAM 2.1...';
 const statusNode=$('itcvRigStatus');
 if(statusNode)statusNode.textContent='Menghubungkan ke server lokal SAM 2.1 di http://127.0.0.1:11436/api/health ...';
 const controller=new AbortController();
 const timer=window.setTimeout(()=>controller.abort(),9000);
 try{
  const response=await fetch('http://127.0.0.1:11436/api/health',{method:'GET',mode:'cors',credentials:'omit',cache:'no-store',signal:controller.signal});
  let result;try{result=await response.json();}catch(_){throw new Error('Respons server lokal bukan JSON yang valid.');}
  if(!response.ok||!result.ok)throw new Error(result.error||('HTTP '+response.status));
  if(result.checkpoint===false)throw new Error('Checkpoint sam2.1_hiera_tiny.pt tidak ditemukan. Jalankan setup SAM 2.1.');
  const device=result.device==='unloaded'?'perangkat dipilih otomatis saat inferensi':(result.device||'auto');
  button.textContent='SAM 2.1 Terhubung';
  if(statusNode)statusNode.textContent='SAM 2.1 Tiny terhubung · '+device+' · '+(result.model_loaded?'model sudah aktif':'checkpoint terdeteksi; model dimuat saat segmentasi pertama')+'.';
 }catch(error){
  button.textContent='Cek Segmenter Lokal';
  const message=error.name==='AbortError'?'Server lokal tidak merespons dalam 9 detik. Pastikan TROZAL_UNIVERSAL_RIG_START.bat tetap berjalan.':(error.message||String(error));
  if(statusNode)statusNode.textContent='Pemeriksaan SAM 2.1 gagal: '+message+' Jika API aktif tetapi browser menolak koneksi, periksa izin Local Network/CORS.';
 }finally{
  window.clearTimeout(timer);button.disabled=false;delete button.dataset.checking;
 }
},true);
