let visionModels=[];
function visionBase(){if(typeof window.trozalVisionBaseUrl!=='function')throw new Error('Bridge Ollama belum terhubung. Jalankan bridge lokal TROZAL terlebih dahulu.');const base=String(window.trozalVisionBaseUrl());return base.endsWith('/')?base.slice(0,-1):base}
function isVisionModel(name){const n=String(name||'').toLowerCase();return VISION_HINTS.some(h=>n.includes(h));}
async function refreshVisionModels(){const sel=$('itcvVisionModel'),label=$('itcvVisionStatus');label.textContent='Menghubungkan ke Ollama lokal…';try{const r=await fetch(visionBase()+'/api/tags',{cache:'no-store'});if(!r.ok)throw new Error('Ollama HTTP '+r.status);const j=await r.json();const all=(j.models||[]).map(m=>m.name||m.model).filter(Boolean);visionModels=all.filter(isVisionModel);sel.replaceChildren();if(!visionModels.length){const o=document.createElement('option');o.value='';o.textContent='Tidak ada model Vision terpasang';sel.append(o);label.textContent='Belum ada model Vision yang dikenali. Pasang qwen2.5vl:3b lalu Refresh.';return;}visionModels.sort((a,b)=>(a.toLowerCase().includes('qwen2.5vl:3b')?-1:0)-(b.toLowerCase().includes('qwen2.5vl:3b')?-1:0));visionModels.forEach(name=>{const o=document.createElement('option');o.value=name;o.textContent=name;sel.append(o);});const preferred=visionModels.find(x=>x.toLowerCase().startsWith('qwen2.5vl:3b'))||visionModels.find(x=>x.toLowerCase().includes('qwen'))||visionModels[0];sel.value=preferred;label.textContent=visionModels.length+' model Vision lokal ditemukan. Terpilih: '+preferred;}catch(e){sel.replaceChildren();const o=document.createElement('option');o.value='';o.textContent='Bridge belum tersedia';sel.append(o);label.textContent=e.message||String(e);}}
async function testVision(){const label=$('itcvVisionStatus');if(!files.length){label.textContent='Pilih gambar terlebih dahulu untuk menguji Vision.';return;}const model=$('itcvVisionModel').value;if(!model){label.textContent='Tidak ada model Vision. Pasang model lalu Refresh.';return;}const b=$('itcvTestVision');b.disabled=true;try{const image=uris[0]||await read(files[0]);uris[0]=image;const visionImage=await optimizeVisionImage(image);const numCtx=Number($('itcvContext').value)||4096;const requestBody={model,messages:[{role:'user',content:'Describe the main subject, visible text, layout and background in this image. Reply in concise Indonesian.',images:[visionImage.split(',')[1]]}],stream:false,options:{temperature:.2,num_ctx:numCtx,num_predict:180}};let r=await fetch(visionBase()+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody)});let j=await r.json();if(!r.ok&&/context|token|too large|exceed/i.test(j.error||'')&&numCtx!==4096){requestBody.options.num_ctx=4096;requestBody.options.num_predict=120;r=await fetch(visionBase()+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(requestBody)});j=await r.json();}if(!r.ok)throw new Error(j.error||'Ollama HTTP '+r.status);const answer=j.message?.content||'';if(!answer.trim())throw new Error('Model tidak mengembalikan jawaban.');label.textContent='VISION BERHASIL · '+model+' — '+answer.slice(0,240);}catch(e){label.textContent='Uji Vision gagal: '+(e.message||e);}finally{b.disabled=false;}}
