  status('Frame selesai direkam ('+(webm.size/1048576).toFixed(1)+' MB). Memuat FFmpeg lokal untuk konversi MP4 H.264…');
  const pkg=new URL('vendor/ffmpeg/',document.baseURI).href,core=new URL('vendor/prores-core/',document.baseURI).href;
