  const width=frameCanvas.width,height=frameCanvas.height;
  const result=await ffmpeg.exec(['-y','-i','mode5-input.webm','-an','-c:v','libx264','-preset','veryfast','-crf','18','-pix_fmt','yuv420p','-r',String(fps),'-movflags','+faststart','mode5-output.mp4']);
  if(result!==0)throw new Error('FFmpeg gagal meng-encode MP4 (exit '+result+').');
  const data=await ffmpeg.readFile('mode5-output.mp4');
